using Marina.Persistence.Data; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace Marina.Api.Controllers;
[ApiController,Route("api/v1/catalog"),Microsoft.AspNetCore.RateLimiting.EnableRateLimiting("public")]
public sealed class CatalogController(MarinaDbContext db):ControllerBase{
 [HttpGet("home")]public async Task<ActionResult>Home([FromQuery]string culture="en"){culture=Culture(culture);var categories=await db.Categories.AsNoTracking().Where(x=>x.IsActive&&x.ParentId==null&&!x.IsDeleted).OrderBy(x=>x.SortOrder).Take(12).Select(x=>new{x.Id,x.Slug,Name=x.Translations.Where(t=>t.Culture==culture).Select(t=>t.Name).FirstOrDefault()}).ToListAsync();var products=await Query(culture).Where(x=>x.IsFeatured||x.IsNewArrival||x.IsOffer).OrderByDescending(x=>x.CreatedUtc).Take(16).Select(ProductProjection(culture)).ToListAsync();return Ok(new{hero=new{title=culture=="ar"?"أناقة لكل حكاية":"Timeless style for every story",subtitle=culture=="ar"?"قطع مختارة لكل أفراد العائلة":"Curated pieces for the whole family"},categories,products});}
 [HttpGet("categories")]public async Task<ActionResult>Categories([FromQuery]string culture="en")=>Ok(await db.Categories.AsNoTracking().Where(x=>x.IsActive&&!x.IsDeleted).OrderBy(x=>x.SortOrder).Select(x=>new{x.Id,x.ParentId,x.Slug,Name=x.Translations.Where(t=>t.Culture==Culture(culture)).Select(t=>t.Name).FirstOrDefault()}).ToListAsync());
 [HttpGet("products")]public async Task<ActionResult>Products([FromQuery]int page=1,[FromQuery]int pageSize=20,[FromQuery]string?search=null,[FromQuery]Guid?categoryId=null,[FromQuery]Guid?brandId=null,[FromQuery]decimal?minPrice=null,[FromQuery]decimal?maxPrice=null,[FromQuery]string?size=null,[FromQuery]string?color=null,[FromQuery]bool?offers=null,[FromQuery]bool?featured=null,[FromQuery]bool?newArrivals=null,[FromQuery]string sort="newest",[FromQuery]string culture="en"){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,50);culture=Culture(culture);var q=Query(culture);if(!string.IsNullOrWhiteSpace(search)){var term=search.Trim();q=q.Where(x=>x.Translations.Any(t=>t.Name.Contains(term))||x.Variants.Any(v=>v.Sku.Contains(term)));}if(categoryId.HasValue)q=q.Where(x=>x.CategoryId==categoryId||x.Category.ParentId==categoryId);if(brandId.HasValue)q=q.Where(x=>x.BrandId==brandId);q=q.Where(x=>x.Variants.Any(v=>v.IsActive&&!v.IsDeleted&&(!minPrice.HasValue||v.Price>=minPrice)&&(!maxPrice.HasValue||v.Price<=maxPrice)&&(size==null||size==""||v.Size!.Code==size)&&(color==null||color==""||v.Color!.Code==color)));if(offers.HasValue)q=q.Where(x=>x.IsOffer==offers);if(featured.HasValue)q=q.Where(x=>x.IsFeatured==featured);if(newArrivals.HasValue)q=q.Where(x=>x.IsNewArrival==newArrivals);q=sort switch{"price_asc"=>q.OrderBy(x=>x.Variants.Where(v=>v.IsActive&&!v.IsDeleted).Min(v=>v.Price)),"price_desc"=>q.OrderByDescending(x=>x.Variants.Where(v=>v.IsActive&&!v.IsDeleted).Min(v=>v.Price)),"name"=>q.OrderBy(x=>x.Translations.Where(t=>t.Culture==culture).Select(t=>t.Name).FirstOrDefault()),_=>q.OrderByDescending(x=>x.CreatedUtc)};var total=await q.CountAsync();var items=await q.Skip((page-1)*pageSize).Take(pageSize).Select(ProductProjection(culture)).ToListAsync();return Ok(new{items,page,pageSize,total,totalPages=(int)Math.Ceiling(total/(double)pageSize)});}
 [HttpGet("products/{id:guid}")]public async Task<ActionResult>Product(Guid id,[FromQuery]string culture="en"){culture=Culture(culture);var item=await Query(culture).Where(x=>x.Id==id).Select(x=>new{x.Id,Name=x.Translations.Where(t=>t.Culture==culture).Select(t=>t.Name).FirstOrDefault(),Description=x.Translations.Where(t=>t.Culture==culture).Select(t=>t.Description).FirstOrDefault(),Images=x.Images.OrderBy(i=>i.SortOrder).Select(i=>new{i.Url,i.AltText}),Variants=x.Variants.Where(v=>v.IsActive&&!v.IsDeleted).Select(v=>new{v.Id,v.Sku,v.Price,v.CompareAtPrice,Color=v.Color!.Translations.Where(t=>t.Culture==culture).Select(t=>t.Name).FirstOrDefault(),ColorHex=v.Color!.Hex,Size=v.Size!.Translations.Where(t=>t.Culture==culture).Select(t=>t.Name).FirstOrDefault(),Available=v.Inventory.Quantity-v.Inventory.ReservedQuantity>0,AvailableQuantity=v.Inventory.Quantity-v.Inventory.ReservedQuantity})}).SingleOrDefaultAsync();return item is null?NotFound():Ok(item);}
 private IQueryable<Marina.Domain.Catalog.Product>Query(string culture)=>db.Products.AsNoTracking().Where(x=>x.IsActive&&!x.IsDeleted&&x.Category.IsActive&&!x.Category.IsDeleted&&(x.Brand==null||(x.Brand.IsActive&&!x.Brand.IsDeleted))&&x.Variants.Any(v=>v.IsActive&&!v.IsDeleted&&v.Inventory!=null&&!v.Inventory.IsDeleted));private static System.Linq.Expressions.Expression<Func<Marina.Domain.Catalog.Product,object>>ProductProjection(string culture)=>x=>new{x.Id,x.Slug,Name=x.Translations.Where(t=>t.Culture==culture).Select(t=>t.Name).FirstOrDefault(),VariantId=x.Variants.Where(v=>v.IsActive&&!v.IsDeleted).OrderBy(v=>v.Price).Select(v=>v.Id).FirstOrDefault(),Price=x.Variants.Where(v=>v.IsActive&&!v.IsDeleted).Min(v=>v.Price),CompareAtPrice=x.Variants.Where(v=>v.IsActive&&!v.IsDeleted).Min(v=>v.CompareAtPrice),Image=x.Images.OrderBy(i=>i.SortOrder).Select(i=>i.Url).FirstOrDefault(),x.IsFeatured,x.IsNewArrival,x.IsOffer};private static string Culture(string value)=>value.Equals("ar",StringComparison.OrdinalIgnoreCase)?"ar":"en";
}
